// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(186000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    const errors: string[] = [];
    page.on('pageerror', (e) => errors.push(e.message));

    await page.goto(`${baseUrl}/`);
    await page.getByTestId("dropdown-menu-button").click();
    await expect(page.getByTestId("toolbar-laser")).toBeHidden();
    await expect(page.getByRole("menuitem")).toHaveCount(6);
    await expect(page.getByTestId("toolbar-frame")).toHaveText(/Frame tool\s*F/);
    await expect(page.getByTestId("toolbar-lasso")).toHaveText("Lasso selection");
    await page.getByTestId("toolbar-frame").click();
    await expect(page.getByRole("menuitem")).toHaveCount(0);
    await expect(page.getByRole("button", { name: "Send to back — Ctrl+Shift+[" })).toBeVisible();

    expect(errors).toHaveLength(0);
});
